       "body": "**작성내용**[법 제25조]: 안전 및 보건에 관한 관리조직과 그 직무 / 안전보건교육 / 작업장의 안전 및 보건 관리 / 사고 조사 및 대책 수립 / 그 밖에 안전 및 보건에 관한 사항\n**작성대상**[시행규칙 별표 2]: 농업·어업·소프트웨어 개발 및 공급업·금융 및 보험업 등 10개 업종은 **상시근로자 300명 이상**, 그 외 사업은 **상시근로자 100명 이상**\n**작성·변경 절차**[법 제26조]: **산업안전보건위원회의 심의·의결**을 거쳐야 하며, 위원회가 없으면 **근로자대표의 동의**를 받아야 한다\n**작성 시 유의사항**: 법정기준을 **상회**하도록 할 것 / 관리자층의 직무·권한을 명확히 할 것 / 관계법령 제·개정에 따라 즉시 개정 / 현장의 의견 반영 / 정상 시는 물론 이상 시·사고 시·재해발생 시 조치와 기준도 규정",
