       "body": "1 법령에 규정된 방법으로 조치\n2 위험한 작업의 폐지·변경, 기계·물질의 대체 등 **본질적 제거**\n3 인터록·안전장치·방호문·국소배기장치 등 **공학적 대책**\n4 작업 매뉴얼 정비, 출입금지·작업허가 제도, 교육 등 **관리적 대책**\n5 **개인보호구 사용**(최후의 방법)",
